//! Build 2 Part 7, D38: the SEC relay as `deploy/prod/feeds/sec.py` emits it, published with the public test rule on
//! (`publish_stored_checked`, the call the binary makes on datumesh-http) on a mesh-test-like config, so every
//! descriptor goes through core's checks (spec 7.1: a number declares its unit) and every cell through the store's.
//!
//! The files are generated by `fixtures/make_sec_stub.py` from `sec.emit` (never by hand):
//!
//! * `sec_views_stub_relay.jsonl`: the saved companyfacts of Caterpillar and JPMorgan Chase, with the
//!   source-conformance tests of the saved Assets frame (the relay the views read);
//! * `sec_relay_forms.jsonl`: one synthetic company holding every unit form (D38): money in three currencies,
//!   shares, per share in two currencies and a pure number.
//!
//! Checked: both are accepted and a second run changes nothing; the live mesh answers a cell of every unit form;
//! the descriptor that failed on mesh-test (a number return without a unit) is refused with `E_CANON_UNIT` at
//! `$.signature.returns`; a string `fiscal_year` of `filing_for` and a `{"type": "string"}` return are refused too.

mod common;

use std::path::PathBuf;
use std::sync::Arc;

use common::lite::{Lite, HOST, NOW};
use common::pub031::{opts, write};
use common::{key_doc, key_for, Node, Setup, TestDb, BIND_TX};
use datumesh_http::publish::publish_stored_checked;
use serde_json::{json, Value};

fn feeds() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("deploy/prod/feeds")
}

fn lines(name: &str) -> Vec<String> {
    let p = feeds().join("fixtures").join(name);
    std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display())).lines().map(str::to_string).collect()
}

fn json_of(l: &str) -> Value {
    serde_json::from_str(l).unwrap()
}

fn relay(name: &str) -> String {
    format!("{HOST}/relay/sec.gov/{name}")
}

fn count(ls: &[String], key: &str) -> usize {
    ls.iter().filter(|l| json_of(l).get(key).is_some()).count()
}

fn publish(lite: &Lite, ls: &[String]) -> Result<datumesh_http::publish::Published, datumesh_http::publish::PublishError> {
    let f = write(lite, "relay.jsonl", ls);
    publish_stored_checked(&*lite.store, &lite.key, HOST, &[HOST.to_string()], &f, &opts(NOW))
}

#[test]
fn the_stub_relay_publishes_under_the_public_rule_and_a_second_run_changes_nothing() {
    let ls = lines("sec_views_stub_relay.jsonl");
    let lite = Lite::new("sr-stub");
    let p = publish(&lite, &ls).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(p.functions, 5, "company_fact, company_fact_shares, company_fact_per_share, filing, filing_for: {p:?}");
    assert_eq!(p.cells as usize, count(&ls, "cell"), "{p:?}");
    assert!(p.cells > 800, "{p:?}");
    let again = publish(&lite, &ls).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!((again.functions, again.versions), (0, 0), "{again:?}");
}

#[test]
fn every_unit_form_publishes_with_its_descriptor() {
    let ls = lines("sec_relay_forms.jsonl");
    let lite = Lite::new("sr-forms");
    let p = publish(&lite, &ls).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(p.functions, 6, "four fact functions (money, shares, per share, pure number), filing, filing_for: {p:?}");
    assert_eq!(p.cells as usize, count(&ls, "cell"), "{p:?}");
    let fns: Vec<String> = ls.iter().filter_map(|l| json_of(l).get("function").map(|f| f.as_str().unwrap().to_string())).collect();
    for n in ["company_fact", "company_fact_shares", "company_fact_per_share", "company_fact_ratio", "filing", "filing_for"] {
        assert!(fns.contains(&relay(n)), "{n}");
        assert!(lite.bound_tx(&relay(n)).is_some(), "{n} unbound");
    }
    // the cells of the three left-out units (Liabilities in CAD/EUR, Revenues in acre, NetIncomeLoss in USD-per-gal)
    // are not in the file: seven cells are
    let facts = ls
        .iter()
        .filter(|l| json_of(l).pointer("/cell/fn").is_some_and(|f| f.as_str().unwrap().contains("/company_fact")))
        .count();
    assert_eq!(facts, 7);
}

fn signature_of(ls: &[String], name: &str) -> Value {
    ls.iter().map(|l| json_of(l)).find(|v| v["function"] == relay(name).as_str()).unwrap()["signature"].clone()
}

#[test]
fn the_descriptors_are_the_ones_d38_names() {
    let ls = lines("sec_relay_forms.jsonl");
    assert_eq!(signature_of(&ls, "company_fact")["returns"], json!({"type": "number", "unit": {"arg": "unit"}}));
    assert_eq!(signature_of(&ls, "company_fact_shares")["returns"], json!({"type": "number", "unit": "count"}));
    assert_eq!(signature_of(&ls, "company_fact_shares")["order"], json!(["cik", "taxonomy", "concept", "accession", "period"]));
    assert_eq!(signature_of(&ls, "company_fact_per_share")["returns"], json!({"type": "number", "unit": {"arg": "currency"}}));
    assert_eq!(
        signature_of(&ls, "company_fact_per_share")["order"],
        json!(["cik", "taxonomy", "concept", "currency", "accession", "period"])
    );
    assert_eq!(signature_of(&ls, "company_fact_ratio")["returns"], json!({"type": "number", "unit": "1"}));
    assert_eq!(signature_of(&ls, "filing")["returns"], json!("string"));
    assert_eq!(signature_of(&ls, "filing_for")["returns"], json!("string"));
    assert_eq!(signature_of(&ls, "filing_for")["args"]["fiscal_year"], json!({"type": "number", "unit": "1", "valid": false}));
}

/// The refusals the real load showed, kept as tests: the fetcher's earlier descriptors cannot come back.
fn refused_with(label: &str, change: impl Fn(&mut Value), want: &[&str]) {
    let mut ls = lines("sec_relay_forms.jsonl");
    for l in ls.iter_mut() {
        let mut v = json_of(l);
        if v.get("function").is_some() {
            change(&mut v);
            *l = v.to_string();
        }
    }
    let lite = Lite::new(label);
    let e = publish(&lite, &ls).expect_err("refused");
    for w in want {
        assert!(e.detail.contains(w) || e.to_string().contains(w), "{label}: {w} not in {e} / {}", e.detail);
    }
}

#[test]
fn a_number_return_without_a_unit_is_refused_as_it_was_on_mesh_test() {
    refused_with(
        "sr-nounit",
        |v| {
            if v["function"] == relay("company_fact").as_str() {
                v["signature"]["returns"] = json!({"type": "number"});
            }
        },
        &["E_CANON_UNIT", "$.signature.returns"],
    );
}

#[test]
fn a_string_return_written_as_an_object_and_a_string_fiscal_year_are_not_what_the_fetcher_emits() {
    refused_with(
        "sr-strobj",
        |v| {
            if v["function"] == relay("filing").as_str() {
                v["signature"]["returns"] = json!({"type": "string"});
            }
        },
        &["E_CANON_UNIT"],
    );
    // `unit` on a string argument is E_CANON_UNIT too
    refused_with(
        "sr-strunit",
        |v| {
            if v["function"] == relay("filing_for").as_str() {
                v["signature"]["args"]["cik"] = json!({"type": "string", "unit": "1", "valid": false});
            }
        },
        &["E_CANON_UNIT"],
    );
}

fn path_of(call: &str) -> String {
    let (name, rest) = call.split_once('(').unwrap();
    let args = rest.strip_suffix(')').unwrap();
    let mut q: Vec<String> = args
        .split(", ")
        .map(|a| {
            let (k, v) = a.split_once(": ").unwrap();
            format!("{k}={}", v.trim_matches('"'))
        })
        .collect();
    q.sort();
    format!("/cell/{name}?{}", q.join("&"))
}

/// The live mesh answers a cell of every unit form with the figure as filed.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn the_live_mesh_answers_a_cell_of_every_unit_form() {
    let db = Arc::new(TestDb::migrated());
    let key = key_for(HOST);
    let store = Arc::new(common::bl(|| db.store(8)));
    common::bl(|| store.put_namespace(HOST, &key_doc(HOST, &key), BIND_TX).unwrap());
    let dir = common::out_dir().join(format!("sec-relay-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let ls = lines("sec_relay_forms.jsonl");
    let p = dir.join("forms.jsonl");
    std::fs::write(&p, ls.iter().map(|l| format!("{l}\n")).collect::<String>()).unwrap();
    common::bl(|| publish_stored_checked(&*store, &key, HOST, &[HOST.to_string()], &p, &opts(NOW))).unwrap_or_else(|e| panic!("{e}"));
    let node = Node::start_with(Setup { db: Some(db.clone()), ..Setup::new(HOST) }, |_| {}, |b| b).await;
    // one example of each fact function, from its own catalogue entry
    let mut seen = 0;
    for l in &ls {
        let v = json_of(l);
        if v.get("catalog").is_none() || !v["catalog"].as_str().unwrap().contains("company_fact") {
            continue;
        }
        for e in v["examples"].as_array().unwrap() {
            let call = e["call"].as_str().unwrap();
            let r = node.get(&path_of(call)).await;
            let a: Value = serde_json::from_slice(&r.body).unwrap_or_else(|x| panic!("{call}: {x}: {}", r.text()));
            assert_eq!(a["outcome"], "ok", "{call}: {a}");
            assert_eq!(a["receipt"]["value"], e["expected"]["value"], "{call}: {a}");
            seen += 1;
        }
    }
    assert!(seen >= 4, "an example for each of the four fact functions: {seen}");
}
